SELECT analytics_order_facts.channel, SUM(analytics_order_facts.net_revenue) / CAST(NULLIF(COUNT(DISTINCT analytics_order_facts.order_id), 0) AS DECIMAL) AS average_order_value FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 6 AND analytics_order_facts.region = 'South' AND analytics_order_facts.customer_segment = 'mid_market' AND analytics_order_facts.payment_method = 'debit' GROUP BY analytics_order_facts.channel ORDER BY average_order_value DESC, analytics_order_facts.channel ASC LIMIT 12
